//! Renders every target and compares or writes it: whole generated files, and
//! generated blocks inside hand-written ones.

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use crate::schema::Entry;
use crate::{emit_java, emit_jvm_rs, emit_py, emit_pyclass, emit_pyi};

pub enum Kind {
    /// The file is generated end to end.
    Whole,
    /// The text between two marker lines of a hand-written file.
    Block { begin: String, end: String },
}

pub struct Target {
    pub path: PathBuf,
    pub body: String,
    pub kind: Kind,
}

/// Why a target cannot be produced from what is on disk.
pub enum Gap {
    Absent,
    NoMarkers(String),
}

/// What the tool prints when rustfmt cannot format the generated Rust.
const NEEDS_RUSTFMT: &str = "rustfmt is needed to format the generated Rust files \
     (`rustup component add rustfmt`)";

/// Runs `text` through the workspace's rustfmt so the committed file is
/// what `cargo fmt --check` accepts.
pub fn rustfmt(text: &str, root: &Path) -> Result<String, String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--config-path"])
        .arg(root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("{NEEDS_RUSTFMT}: cannot run rustfmt: {e}"))?;
    child
        .stdin
        .take()
        .expect("piped stdin")
        .write_all(text.as_bytes())
        .map_err(|e| format!("rustfmt stdin: {e}"))?;
    let out = child
        .wait_with_output()
        .map_err(|e| format!("rustfmt: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "{NEEDS_RUSTFMT}: rustfmt failed:\n{}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    String::from_utf8(out.stdout).map_err(|e| e.to_string())
}

/// The marker lines of a block, in the comment syntax of the host file
/// (`#` for Python, `//` for Java).
fn markers(comment: &str, name: &str) -> (String, String) {
    (
        format!("{comment} BEGIN GENERATED by print-records ({name}); do not edit"),
        format!("{comment} END GENERATED by print-records ({name})"),
    )
}

/// Every target of the registry, in a stable order, as the emitters produce
/// it: the generated Rust files are not yet formatted (see [`formatted`]).
pub fn targets(root: &Path, reg: &[Entry]) -> Result<Vec<Target>, String> {
    let mut out = Vec::new();
    let mut families: Vec<&str> = Vec::new();
    for e in reg {
        if !families.contains(&e.family) {
            families.push(e.family);
        }
    }
    for f in &families {
        if reg.iter().any(|e| e.family == *f && e.python) {
            out.push(Target {
                path: root.join(format!("bindings/python/src/generated/{f}.rs")),
                body: emit_py::file(reg, f)?,
                kind: Kind::Whole,
            });
        }
        if reg.iter().any(|e| e.family == *f && e.jvm && e.jvm_builder) {
            out.push(Target {
                path: root.join(format!("bindings/jvm/src/generated/{f}.rs")),
                body: emit_jvm_rs::file(reg, f)?,
                kind: Kind::Whole,
            });
        }
    }
    for e in reg {
        let name = e.name();
        let module = e.py_module.replace('.', "/");
        let (begin, end) = markers("#", name);
        // A native class has no `.py` definition: the module re-exports it
        // from the extension.
        if e.python && !e.is_native() {
            out.push(Target {
                path: root.join(format!("bindings/python/python/{module}.py")),
                body: emit_pyi::py_block(reg, e)?,
                kind: Kind::Block {
                    begin: begin.clone(),
                    end: end.clone(),
                },
            });
        }
        if e.python {
            out.push(Target {
                path: root.join(format!("bindings/python/python/{module}.pyi")),
                body: if e.is_native() {
                    emit_pyclass::pyi_block(reg, e)?
                } else {
                    emit_pyi::pyi_block(reg, e)?
                },
                kind: Kind::Block { begin, end },
            });
        }
        if e.jvm {
            let (begin, end) = markers("//", name);
            out.push(Target {
                path: root.join(format!(
                    "bindings/jvm/src/main/java/{}/{name}.java",
                    e.java_pkg
                )),
                body: emit_java::block(reg, e)?,
                kind: Kind::Block { begin, end },
            });
        }
    }
    Ok(out)
}

/// The targets with every generated Rust file run through rustfmt, which is
/// the text `--write` commits and `--check` compares. Only the tool calls
/// this; the emitter tests compare the unformatted text.
pub fn formatted(mut targets: Vec<Target>, root: &Path) -> Result<Vec<Target>, String> {
    for t in &mut targets {
        if t.path.extension().is_some_and(|x| x == "rs") {
            t.body = rustfmt(&t.body, root)?;
        }
    }
    Ok(targets)
}

/// The file content the target should have, or why that cannot be said.
pub fn expected(t: &Target) -> Result<String, Gap> {
    match &t.kind {
        Kind::Whole => Ok(t.body.clone()),
        Kind::Block { begin, end } => {
            let text = std::fs::read_to_string(&t.path).map_err(|_| Gap::Absent)?;
            let lines: Vec<&str> = text.split_inclusive('\n').collect();
            let find = |m: &str, from: usize| {
                lines
                    .iter()
                    .enumerate()
                    .skip(from)
                    .find(|(_, l)| l.trim() == m)
                    .map(|(i, _)| i)
            };
            let b = find(begin, 0).ok_or_else(|| Gap::NoMarkers(begin.clone()))?;
            let e = find(end, b + 1).ok_or_else(|| Gap::NoMarkers(end.clone()))?;
            let mut out: String = lines[..=b].concat();
            out.push_str(&t.body);
            out.push_str(&lines[e..].concat());
            Ok(out)
        }
    }
}

/// The targets whose committed text differs, with the reason.
pub fn stale(targets: &[Target]) -> Vec<(PathBuf, String)> {
    let mut out = Vec::new();
    for t in targets {
        match expected(t) {
            Ok(text) => match std::fs::read_to_string(&t.path) {
                Err(_) => out.push((t.path.clone(), "is absent".to_string())),
                Ok(have) if have != text => {
                    out.push((t.path.clone(), "differs from the schema".to_string()));
                }
                Ok(_) => {}
            },
            Err(Gap::Absent) => out.push((t.path.clone(), "is absent".to_string())),
            Err(Gap::NoMarkers(m)) => out.push((t.path.clone(), format!("has no line `{m}`"))),
        }
    }
    out
}

/// Where generated files and blocks can live.
const GENERATED_ROOTS: &[&str] = &[
    "bindings/python/src/generated",
    "bindings/jvm/src/generated",
    "bindings/jvm/src/main/java",
    "bindings/python/python",
];

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = std::fs::read_dir(dir) else {
        return;
    };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            walk(&p, out);
        } else if p
            .extension()
            .is_some_and(|x| x == "rs" || x == "java" || x == "py" || x == "pyi")
        {
            out.push(p);
        }
    }
}

/// Generated text no target renders: a file that starts with the generated
/// header line, or a block marker, left behind by a record that is no
/// longer registered.
pub fn orphans(root: &Path, targets: &[Target]) -> Vec<(PathBuf, String)> {
    let mut files = Vec::new();
    for r in GENERATED_ROOTS {
        walk(&root.join(r), &mut files);
    }
    files.sort();
    let mut out = Vec::new();
    for f in files {
        let Ok(text) = std::fs::read_to_string(&f) else {
            continue;
        };
        let owned =
            |want: &dyn Fn(&Kind) -> bool| targets.iter().any(|t| t.path == f && want(&t.kind));
        if text.starts_with("// GENERATED by print-records")
            && !owned(&|k| matches!(k, Kind::Whole))
        {
            out.push((
                f.clone(),
                "is generated but no registered record renders it".into(),
            ));
        }
        for line in text.lines() {
            let l = line.trim();
            if (l.starts_with("# BEGIN GENERATED by print-records")
                || l.starts_with("// BEGIN GENERATED by print-records"))
                && !owned(&|k| matches!(k, Kind::Block { begin, .. } if begin == l))
            {
                out.push((
                    f.clone(),
                    format!("has `{l}` but no registered record renders it"),
                ));
            }
        }
    }
    out
}

/// Writes every target; a block target without its markers is an error.
pub fn write_all(targets: &[Target]) -> Result<(), String> {
    for t in targets {
        let text = match expected(t) {
            Ok(text) => text,
            Err(Gap::Absent) => return Err(format!("{}: file is absent", t.path.display())),
            Err(Gap::NoMarkers(m)) => {
                return Err(format!("{}: no line `{m}`", t.path.display()));
            }
        };
        if let Some(dir) = t.path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
        std::fs::write(&t.path, text).map_err(|e| format!("{}: {e}", t.path.display()))?;
    }
    Ok(())
}
